export async function runInReadOnlyTransaction<T>(
  prisma: PrismaClient,
  run: (tx: Prisma.TransactionClient) => Promise<T>,
): Promise<T> {
  return prisma.$transaction(async (tx) => {
    await tx.$executeRawUnsafe(READ_ONLY_TRANSACTION_SQL);
    return run(tx);
  });
}

